import os
import sys
import requests

def main():
    if len(sys.argv) < 2:
        print("Usage: python invoice_summary.py YYYY-MM-DD", file=sys.stderr)
        sys.exit(1)

    date = sys.argv[1]
    token = os.getenv("INVOICE_API_TOKEN")

    if not token:
        print("missing token", file=sys.stderr)
        sys.exit(2)

    headers = {"Authorization": f"Bearer {token}"}
    url = f"https://api.example.com/v1/invoices?date={date}"

    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        if response.status_code == 401:
            print("unauthorized", file=sys.stderr)
            sys.exit(3)
        else:
            print(response.status_code, file=sys.stderr)
            sys.exit(4)

    data = response.json()
    invoices = data.get("invoices", [])

    if not invoices:
        return

    print("id,total_cents")
    for invoice in invoices:
        total_cents = sum(item["amount_cents"] * item["quantity"] for item in invoice["line_items"])
        print(f"{invoice['id']},{total_cents}")

if __name__ == "__main__":
    main()

